impl CatModelVariant {
    pub fn for_resource_id(resource_id: &str) -> Option<Self> {
        VANILLA_CAT_VARIANTS
            .iter()
            .find(|entry| entry.resource_id == resource_id)
            .map(|entry| entry.variant)
    }

    pub fn for_vanilla_registry_id(registry_id: i32) -> Option<Self> {
        VANILLA_CAT_VARIANTS
            .get(usize::try_from(registry_id).ok()?)
            .map(|entry| entry.variant)
    }

    pub fn resource_id(self) -> &'static str {
        VANILLA_CAT_VARIANTS[self as usize].resource_id
    }

    pub const fn builtin_texture_ref(self, baby: bool) -> EntityModelTextureRef {
        let age_offset = if baby { 1 } else { 0 };
        VANILLA_CAT_VARIANT_TEXTURE_REFS
            [VANILLA_CAT_VARIANTS[self as usize].texture_start + age_offset]
    }
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn cat_variant_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_CAT_VARIANTS.len(), 11);
        let mut resources = HashSet::new();
        let mut textures = HashSet::new();
        for (registry_id, entry) in VANILLA_CAT_VARIANTS.iter().enumerate() {
            assert_eq!(entry.variant as usize, registry_id);
            assert_eq!(entry.texture_start, registry_id * 2);
            assert!(resources.insert(entry.resource_id));
        }
        for texture in VANILLA_CAT_VARIANT_TEXTURE_REFS {
            assert!(textures.insert(texture.path));
        }
    }

    #[test]
    fn cat_variant_catalog_preserves_registry_and_resource_order() {
        assert_eq!(
            CatModelVariant::for_vanilla_registry_id(0),
            Some(CatModelVariant::Tabby)
        );
        assert_eq!(
            CatModelVariant::for_vanilla_registry_id(10),
            Some(CatModelVariant::AllBlack)
        );
        assert_eq!(CatModelVariant::for_vanilla_registry_id(-1), None);
        assert_eq!(CatModelVariant::for_vanilla_registry_id(11), None);
        assert_eq!(
            CatModelVariant::for_resource_id("minecraft:jellie"),
            Some(CatModelVariant::Jellie)
        );
        assert_eq!(CatModelVariant::for_resource_id("minecraft:lynx"), None);
        assert_eq!(CatModelVariant::Black.resource_id(), "minecraft:black");
        assert_eq!(
            CatModelVariant::Tabby.builtin_texture_ref(false).path,
            "textures/entity/cat/cat_tabby.png"
        );
        assert_eq!(
            CatModelVariant::Jellie.builtin_texture_ref(true).path,
            "textures/entity/cat/cat_jellie_baby.png"
        );
        assert_eq!(
            CatModelVariant::AllBlack.builtin_texture_ref(true).size,
            [32, 32]
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_cat_variant_catalog_facts() {
        let native = include_str!("../../bbb-native/src/entity_assets.rs");
        let fixture = native
            .split("fn loads_vanilla_entity_textures_from_resource_stack")
            .nth(1)
            .and_then(|source| source.split("    #[test]").next())
            .expect("native entity texture loader fixture");
        assert_eq!(fixture.matches("entity_model_texture_refs()").count(), 3);
        for texture in VANILLA_CAT_VARIANT_TEXTURE_REFS {
            assert!(
                !fixture.contains(texture.path),
                "native fixture restored cat asset literal {}",
                texture.path
            );
        }
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/cat_variants.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum CatModelVariant")
                    || source.contains("fn cat_variant_from_entry_id(")
                    || source.contains("fn cat_variant_from_vanilla_registry_id(")
                    || source.contains("fn vanilla_cat_variant_resource_id(")
                    || source.contains("\"minecraft:tabby\" => Some(CatModelVariant::")
                    || source.contains("const FELINE_CAT_BLACK_TEXTURE_REF")
                    || source.contains("CatModelVariant::Tabby, false) =>")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel cat-variant catalog owners: {violations:?}"
        );
    }
}
